 "content": "def transform(grid):
    """Recolor every occurrence of the template's five-cell mask, any orientation."""
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, _ in points)
    c0 = min(c for _, c in points)
    base = [(r-r0, c-c0) for r, c in points]
    shapes = set()
    for flip in (1, -1):
        for turns in range(4):
            coords = []
            for r, c in base:
                c *= flip
                for _ in range(turns):
                    r, c = c, -r
                coords.append((r, c))
            mr = min(r for r, _ in coords)
            mc = min(c for _, c in coords)
            shapes.add(frozenset((r-mr, c-mc) for r, c in coords))

    out = [row[:] for row in grid]
    for shape in shapes:
        dh = max(r for r, _ in shape)
        dw = max(c for _, c in shape)
        for top in range(h-dh):
            for left in range(w-dw):
                cells = [(top+dr, left+dc) for dr, dc in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = 2
    return out
