 "content": "def transform(grid):
    """Rotate the exact seed mask through 90-degree orientations and stamp it on zero cells."""
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not points:
        return [row[:] for row in grid]
    r0, c0 = min(r for r, _ in points), min(c for _, c in points)
    base = [(r-r0, c-c0) for r, c in points]
    shapes = set()
    for reflect in (1, -1):
        for turns in range(4):
            coords = []
            for r, c in base:
                c *= reflect
                for _ in range(turns):
                    r, c = c, -r
                coords.append((r, c))
            dr0 = min(r for r, _ in coords)
            dc0 = min(c for _, c in coords)
            shapes.add(frozenset((r-dr0, c-dc0) for r, c in coords))

    out = [row[:] for row in grid]
    for shape in shapes:
        max_r = max(r for r, _ in shape)
        max_c = max(c for _, c in shape)
        for top in range(h-max_r):
            for left in range(w-max_c):
                cells = [(top+dr, left+dc) for dr, dc in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = 2
    return out
