 "content": "from collections import Counter

def transform(grid):
    """Stamp the seed mask into placements occupied by the dominant field color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, _ in points)
    c0 = min(c for _, c in points)
    mask = [(r-r0, c-c0) for r, c in points]
    out = [row[:] for row in grid]
    for reflect in (1, -1):
        for turns in range(4):
            coords = []
            for r, c in mask:
                c *= reflect
                for _ in range(turns):
                    r, c = c, -r
                coords.append((r, c))
            dr0 = min(r for r, _ in coords)
            dc0 = min(c for _, c in coords)
            shape = set((r-dr0, c-dc0) for r, c in coords)
            max_r = max(r for r, _ in shape)
            max_c = max(c for _, c in shape)
            for top in range(h-max_r):
                for left in range(w-max_c):
                    cells = [(top+dr, left+dc) for dr, dc in shape]
                    if all(grid[r][c] == background for r, c in cells):
                        for r, c in cells:
                            out[r][c] = 2
    return out
