 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next((v for v, n in counts.items() if v != bg and n < h*w//8), min(counts))
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not pts:
        return [row[:] for row in grid]
    r0, c0 = min(r for r,c in pts), min(c for r,c in pts)
    mask = {(r-r0,c-c0) for r,c in pts}
    out = [row[:] for row in grid]
    H, W = max(r for r,c in mask)+1, max(c for r,c in mask)+1
    for r in range(h-H+1):
        for c in range(w-W+1):
            if all(grid[r+dr][c+dc] == bg for dr,dc in mask):
                for dr,dc in mask:
                    out[r+dr][c+dc] = marker
    return out
